import { dts } from "rolldown-plugin-dts";
//#region src/configs/utils/commonRolldown.ts
const useSources = process.env.USE_SOURCES === "1";
const dtsPlugin = dts({
	sourcemap: true,
	...useSources && { compilerOptions: { customConditions: ["sources"] } }
});
const formatConfig = {
	es: {
		entryFileNames: createEntryFileNames(".js"),
		plugins: [dtsPlugin]
	},
	cjs: { entryFileNames: createEntryFileNames(".cjs") }
};
function createBuildEntry(input, output, format) {
	const { entryFileNames, plugins } = formatConfig[format];
	return {
		input,
		plugins,
		external: (id) => id.startsWith("node:") || /^[^./]/.test(id) && !id.startsWith("@oxc-project/runtime"),
		...useSources && { resolve: { conditionNames: ["sources"] } },
		output: {
			dir: output,
			format,
			entryFileNames,
			sourcemap: true,
			preserveModules: true,
			preserveModulesRoot: "src"
		},
		transform: { target: "ES2022" }
	};
}
function createEntryFileNames(ext) {
	return (chunkInfo) => {
		if (chunkInfo.name.includes("node_modules")) return chunkInfo.name.replace(/node_modules/g, "__external") + ext;
		return `[name]${ext}`;
	};
}
//#endregion
export { createBuildEntry };
